import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';

function snapshot(dir, result = {}) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const file = path.join(dir, entry.name);
    if (entry.isDirectory()) snapshot(file, result);
    else if (file.endsWith('.html')) result[file] = createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  }
  return result;
}
const before = snapshot('dist');
assert.ok(Object.keys(before).length > 0, 'Build the site before testing idempotence.');
execFileSync(process.execPath, ['--import', 'tsx', 'scripts/generate-static-routes.ts'], { stdio: 'inherit' });
assert.deepEqual(snapshot('dist'), before, 'Repeated static generation changed the built HTML.');
console.log(`Static generation is byte-idempotent across ${Object.keys(before).length} HTML files.`);

import assert from 'node:assert/strict';
import test from 'node:test';
import fs from 'node:fs';
import { ALL_ARTICLES, getArticleByPath } from './articleRegistry';
import { PROGRAMMATIC_SEO_PAGES } from './programmaticSeo';
import { getArticleSearchTarget } from '../seo/articleSearchTargets';
import { buildRouteStaticHtml } from '../seo/staticContent';
import { getSeoRoute } from '../seo/routes';
import { PROFILE_FACTS } from './profileFacts';

test('every guide has an existing foundation and a rendered reciprocal link', () => {
  for (const page of PROGRAMMATIC_SEO_PAGES) {
    assert.ok(getArticleByPath(page.foundationalPath), page.path);
    assert.ok(getArticleSearchTarget(page.foundationalPath)?.relatedPaths.includes(page.path));
    assert.ok(buildRouteStaticHtml(getSeoRoute(page.foundationalPath)!).includes(`href="${page.path}"`));
  }
});
test('related diagnostic selection is semantic and excludes itself', () => {
  for (const page of PROGRAMMATIC_SEO_PAGES) {
    const related = page.relatedPaths.map((path) => PROGRAMMATIC_SEO_PAGES.find((item) => item.path === path)).filter(Boolean);
    assert.equal(related.length, 3);
    if (PROGRAMMATIC_SEO_PAGES.some((item) => item.path !== page.path && item.foundationalPath === page.foundationalPath)) {
      assert.ok(related.some((item) => item!.foundationalPath === page.foundationalPath));
    } else {
      assert.ok(related.some((item) => item!.sources.some((source) => page.sources.some((own) => own.href === source.href))));
    }
    assert.ok(related.every((item) => item!.path !== page.path));
  }
});
test('search titles describe evidence without flattening uncertainty', () => {
  const ai = ALL_ARTICLES.find((article) => article.slug === 'the-first-ai-managers')!;
  assert.match(ai.seoTitle!, /30 AI Manager Cases/);
  const austin = ALL_ARTICLES.find((article) => article.slug === 'who-owns-austin-home-service-companies')!;
  assert.match(austin.subtitle!, /unresolved/); assert.doesNotMatch(austin.subtitle!, /verified map/i);
  const magnet = ALL_ARTICLES.find((article) => article.slug === 'us-rare-earth-magnet-manufacturing-capacity')!;
  assert.doesNotMatch(JSON.stringify(magnet), /37,750 (?:metric tonnes|tonnes)|37,750-tonne/);
  assert.match(JSON.stringify(magnet), /37,584–38,048/);
  assert.ok(fs.existsSync('public/research/us-rare-earth-magnet-methodology.md'));
});
test('profile facts and public pages no longer claim a Music degree or obsolete Chegg title', () => {
  assert.equal(PROFILE_FACTS.education.expectedGraduation, 'May 2028');
  assert.deepEqual(PROFILE_FACTS.education.degrees.map((d) => d.field), ['Finance']);
  assert.equal(PROFILE_FACTS.experience[0].title, 'Growth & Product Intern');
  assert.equal(PROFILE_FACTS.experience[0].dates, 'May 2026 — Present');
  for (const path of ['/', '/about', '/resume']) {
    const html = buildRouteStaticHtml(getSeoRoute(path)!);
    assert.doesNotMatch(html, /second degree|BA in Music|AI Product Manager Intern/);
  }
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { isNavItemActive } from './siteNavigation';

test('nested paths activate their actual parent section', () => {
  assert.ok(isNavItemActive('/atlas/sample-crawl', '/atlas'));
  assert.ok(isNavItemActive('/research/technical-seo/issues/noindex', '/research'));
  assert.ok(isNavItemActive('/resume/?print=1', '/resume'));
  assert.ok(isNavItemActive('/markets/who-owns-texas-toll-roads', '/research'));
  assert.ok(isNavItemActive('/markets', '/research'));
});
test('navigation does not confuse prefixes, external URLs, or hash targets', () => {
  assert.equal(isNavItemActive('/atlas-other', '/atlas'), false);
  assert.equal(isNavItemActive('/research', '/'), false);
  assert.equal(isNavItemActive('/research', 'https://example.org/research'), false);
  assert.equal(isNavItemActive('/research', '//example.org/research'), false);
  assert.equal(isNavItemActive('/about#other', '/about#music'), false);
  assert.ok(isNavItemActive('/about#music', '/about#music'));
});

import assert from 'node:assert/strict';
import test from 'node:test';
import { installSmoothScrolling, type ScrollEnvironment } from './smoothScroll';

function harness(initialReduced = false, initialNative = false) {
  const media = [initialReduced, initialNative].map((matches) => {
    const listeners = new Set<() => void>();
    return { matches, listeners, addEventListener: (_: string, listener: () => void) => listeners.add(listener),
      removeEventListener: (_: string, listener: () => void) => listeners.delete(listener),
      set(value: boolean) { this.matches = value; for (const listener of listeners) listener(); } };
  });
  const frames = new Map<number, FrameRequestCallback>();
  const instances: { calls: number; destroyed: number; raf(): void; destroy(): void }[] = [];
  let id = 0;
  const env: ScrollEnvironment = {
    matchMedia: (query) => media[query.includes('reduced') ? 0 : 1] as unknown as MediaQueryList,
    requestAnimationFrame: (callback) => { frames.set(++id, callback); return id; },
    cancelAnimationFrame: (frame) => { frames.delete(frame); },
  };
  const dispose = installSmoothScrolling(env, () => {
    const instance = { calls: 0, destroyed: 0, raf() { this.calls++; }, destroy() { this.destroyed++; } };
    instances.push(instance); return instance;
  });
  return { env, media, frames, instances, dispose };
}

test('desktop scrolling owns one instance and cancels on live reduced-motion change', () => {
  const h = harness();
  assert.equal(h.instances.length, 1); assert.equal(h.frames.size, 1);
  h.media[0].set(false); assert.equal(h.instances.length, 1);
  const tick = [...h.frames.values()][0];
  h.media[0].set(true);
  assert.equal(h.instances[0].destroyed, 1); assert.equal(h.frames.size, 0); assert.equal(h.env.lenis, undefined);
  tick(1); assert.equal(h.frames.size, 0); assert.equal(h.instances[0].calls, 0);
  h.dispose(); assert.equal(h.instances[0].destroyed, 1);
});
test('native device preferences start without Lenis and can return to desktop', () => {
  const h = harness(false, true); assert.equal(h.instances.length, 0);
  h.media[1].set(false); assert.equal(h.instances.length, 1);
  h.media[1].set(true); assert.equal(h.instances[0].destroyed, 1);
  h.media[1].set(false); assert.equal(h.instances.length, 2); assert.equal(h.frames.size, 1);
  h.dispose(); assert.equal(h.instances[1].destroyed, 1); assert.equal(h.frames.size, 0);
  assert.ok(h.media.every((item) => item.listeners.size === 0));
  h.media[0].set(false); assert.equal(h.instances.length, 2);
});
test('cleanup does not delete another owner and strict-mode remount stays independent', () => {
  const h = harness(); h.env.lenis = { anotherOwner: true };
  h.dispose(); assert.deepEqual(h.env.lenis, { anotherOwner: true });
  const native = harness(true, false); assert.equal(native.instances.length, 0); native.dispose();
});
